SELECT *
FROM (
SELECT t.*, ROWNUM rnum
FROM (
SELECT *
FROM chatbot_message
WHERE session_id = #{sessionId}
AND sender IN ('user', 'bot')
ORDER BY created_at DESC
) t
WHERE ROWNUM <= #{offset} + #{limit}
)
WHERE rnum > #{offset}

SELECT *
FROM (
SELECT *
FROM chatbot_message
WHERE session_id = #{sessionId}
ORDER BY created_at DESC
)
WHERE ROWNUM <= #{limit}
